'use strict';

const readline = require('readline');

// ---- size-k min-heap -------------------------------------------------
// Root is always the *worst* element of the current top-k set:
// lower count is worse; among equal counts, the lexicographically
// larger word is worse (final output breaks ties A->Z).
class MinHeap {
  constructor(capacity, worseThan) {
    this.a = new Array(capacity);
    this.size = 0;
    this.capacity = capacity;
    this.worseThan = worseThan;
  }

  worseThan(i, j) {
    const { a } = this;
    return (
      a[i].count < a[j].count ||
      (a[i].count === a[j].count && a[i].word > a[j].word)
    );
  }

  swap(i, j) {
    const { a } = this;
    const t = a[i];
    a[i] = a[j];
    a[j] = t;
  }

  // Returns the evicted element if the heap is full and `item` is better,
  // otherwise stores `item` and returns null.
  offer(item) {
    if (this.size < this.capacity) {
      this.a[this.size++] = item;
      this.up(this.size - 1);
      return null;
    }
    // compare against current worst (root)
    const { a } = this;
    const worse =
      item.count < a[0].count ||
      (item.count === a[0].count && item.word > a[0].word);
    if (worse) return item; // not good enough for top-k
    const evicted = a[0];
    a[0] = item;
    this.down(0);
    return evicted;
  }

  up(i) {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.worseThan(p, i)) break;
      this.swap(p, i);
      i = p;
    }
  }

  down(i) {
    const n = this.size;
    for (;;) {
      const l = 2 * i + 1;
      const r = l + 1;
      let m = i;
      if (l < n && this.worseThan(l, m)) m = l;
      if (r < n && this.worseThan(r, m)) m = r;
      if (m === i) break;
      this.swap(m, i);
      i = m;
    }
  }

  drain() {
    const out = this.a.slice(0, this.size);
    return out;
  }
}

// ---- main ------------------------------------------------------------
async function main() {
  let k = parseInt(process.argv[2], 10);
  if (!Number.isFinite(k) || k <= 0) k = 10;

  const counts = new Map();

  const rl = readline.createInterface({
    input: process.stdin,
    crlfDelay: Infinity,
  });

  rl.on('line', (line) => {
    const words = line.toLowerCase().match(/[a-z]+/g);
    if (!words) return;
    for (let i = 0; i < words.length; i++) {
      const w = words[i];
      counts.set(w, (counts.get(w) || 0) + 1);
    }
  });

  await new Promise((resolve) => rl.on('close', resolve));

  const heap = new MinHeap(k);
  for (const [word, count] of counts) {
    heap.offer({ word, count });
  }

  const top = heap.drain().sort((x, y) =>
    y.count - x.count || (x.word < y.word ? -1 : x.word > y.word ? 1 : 0)
  );

  let out = '';
  for (const { word, count } of top) {
    out += count + ' ' + word + '\n';
  }
  process.stdout.write(out);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
"})
