result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test.js", "content": "'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) >>> 0;
  };
}

function runTopk(args, input) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['topk.js', ...args], {
      cwd: __dirname,
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d));
    child.stderr.on('data', (d) => (stderr += d));
    child.on('error', reject);
    child.on('close', (code) => {
      if (code !== 0) {
        reject(new Error(`exit ${code}: ${stderr}`));
      } else {
        resolve({ stdout, code });
      }
    });
    child.stdin.end(input);
  });
}

test('known frequencies: top 3 exact output', async () => {
  const rand = mulberry32(1337);

  const words = [];
  for (let i = 0; i < 500; i++) words.push('alpha');
  for (let i = 0; i < 300; i++) words.push('beta');
  // 50 filler words with strictly lower counts: 49 down to 0 occurrences
  for (let c = 49; c >= 0; c--) {
    for (let i = 0; i < c; i++) words.push(`filler${c}`);
  }

  // Fisher-Yates shuffle with seeded PRNG
  for (let i = words.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [words[i], words[j]] = [words[j], words[i]];
  }

  const input = words.join('\n') + '\n';
  const { stdout } = await runTopk(['3'], input);
  assert.strictEqual(stdout, '500 alpha\n300 beta\n49 filler49\n');
});

test('empty input prints nothing', async () => {
  const { stdout } = await runTopk(['5'], '');
  assert.strictEqual(stdout, '');
});

test('ties are broken alphabetically', async () => {
  const input = 'zeta zeta zeta Alpha alpha ALPHA mike mike mike bob bob bob\n';
  const { stdout } = await runTopk(['2'], input);
  // all four distinct words have count 3 -> alphabetical top 2
  assert.strictEqual(stdout, '3 alpha\n3 bob\n');

  const { stdout: out3 } = await runTopk(['4'], input);
  assert.strictEqual(out3, '3 alpha\n3 bob\n3 mike\n3 zeta\n');
});

test('scale: 2M words piped through in under 15s', async () => {
  const total = 2_000_000;
  const vocab = [];
  for (let i = 0; i < 1000; i++) vocab.push(`w${i}`);
  const rand = mulberry32(42);

  const tmpFile = path.join(os.tmpdir(), `topk-scale-${process.pid}.txt`);
  const ws = fs.createWriteStream(tmpFile);
  let buf = [];
  for (let i = 0; i < total; i++) {
    buf.push(vocab[Math.floor(rand() * vocab.length)]);
    if (buf.length === 20000) {
      ws.write(buf.join('\n') + '\n');
      buf = [];
    }
  }
  if (buf.length) ws.write(buf.join('\n') + '\n');
  await new Promise((res, rej) => {
    ws.end(res);
    ws.on('error', rej);
  });

  const start = Date.now();
  const { stdout } = await runTopk(['5'], fs.readFileSync(tmpFile));
  const elapsed = Date.now() - start;

  const lines = stdout.trim().split('\n').sort();
  assert.strictEqual(lines.length, 5);
  // every line matches "<count> w<n>"
  for (const line of lines) {
    assert.match(line, /^\d+ w\d+$/);
  }
  // counts must be non-increasing after sort by count desc
  const counts = lines.map((l) => parseInt(l, 10));
  for (let i = 1; i < counts.length; i++) {
    assert.ok(counts[i] <= counts[i - 1]);
  }
  const sum = counts.reduce((a, b) => a + b, 0);
  const maxPossible = Math.ceil(total / vocab.length) + 1000; // sanity bound
  for (const c of counts) assert.ok(c > 0 && c < maxPossible);

  fs.unlinkSync(tmpFile);
  assert.ok(elapsed < 15000, `took ${elapsed}ms, expected < 15000ms`);
  console.log(`   scale run: 2,000,000 words processed in ${(elapsed / 1000).toFixed(2)}s`);
});
"})
